 componentDidUpdate(previous:Readonly<ModelManagementPanel['props']>){if(previous.boot.modelVersion!==this.props.boot.modelVersion||!sameSelection(previous.boot.model,this.props.boot.model)){const selection=this.props.boot.model,version=this.props.boot.modelVersion??0;this.setState(current=>({...current,data:current.data?{...current.data,defaultModel:selection,defaultModelVersion:version}:null,...(!current.defaultDirty?{selection,defaultVersion:version}:{})}));}}
 safeData(data:ManagementData):ManagementData {return {...data,defaultModel:{provider:data.defaultModel.provider,model:data.defaultModel.model,thinking:data.defaultModel.thinking},providers:data.providers.map(({provider,name,enabled,deletedAt,order,source,baseUrl,api,hasApiKey,requiresCredential,models,test})=>({provider,name,enabled,deletedAt,order,source,baseUrl,api,hasApiKey,...(requiresCredential===true?{requiresCredential:true}:{}),models,test}))};}
 observe(data:ManagementData){this.setState(current=>({...current,data,...(!current.defaultDirty?{selection:data.defaultModel,defaultVersion:data.defaultModelVersion}:{})}));}
