   <nav className="settings-provider-list" aria-label="模型提供商"><div className="settings-list-heading"><h2>提供商</h2><button type="button" className="text-button" disabled={locked} onClick={e=>{this.chooseProvider('');this.openEditor('connection',e.currentTarget);}}><Icon name="plus" size={14}/>添加</button></div>{[...new Set(providers.map(brand))].map(group=><div className="management-provider-group" key={group}><h3>{group}</h3>{providers.filter(p=>brand(p)===group).map(p=><div key={p.provider} className="management-provider-row" draggable={!locked} onDragStart={()=>{this.dragged={kind:'providers',id:p.provider,provider:p.provider};}} onDragEnd={()=>{this.dragged=undefined;}} onDragOver={e=>{if(this.dragged?.kind==='providers')e.preventDefault();}} onDrop={e=>{e.preventDefault();if(this.overviewCurrent(s.provider,data.version))this.drop('providers',p.provider);}}><button type="button" disabled={locked} aria-pressed={p.provider===s.provider} onClick={()=>this.chooseProvider(p.provider)}><span className="settings-provider-avatar" aria-hidden="true">{p.name.slice(0,1).toUpperCase()}</span><span className="settings-provider-copy"><strong>{p.name}</strong><small>{p.provider} · {p.enabled?'启用':'已停用'}{p.requiresCredential?' · 待恢复密钥':''}{this.isDefault(p.provider)?' · 默认':''}{own(s.providerDrafts,identity(p.provider))?.dirty?' · 未保存':''}</small></span><Icon name="chevron" size={14}/></button></div>)}</div>)}<p className="small muted management-sort-hint">拖动提供商可调整顺序。</p></nav>
